windows.script:
; Every note is a Markdown file in the notes folder beside the script.
NotesDir := A_ScriptDir "\notes"
Current := ""

LoadNotes(filter := "") {
    global list, NotesDir, g
    DirCreate(NotesDir)
    list.Delete()
    names := [], n := 0
    loop files NotesDir "\*.md" {
        n++
        name := SubStr(A_LoopFileName, 1, -3)
        if (filter = "" || InStr(name, filter))
            names.Push(name)
    }
    if names.Length
        list.Add(names)
    g.Status("count", n " note" (n = 1 ? "" : "s"))
    g.Status("msg", n ? "Pick a note, or start a new one" : "No notes yet: Ctrl+N starts one")
}
OpenNote(name) {
    global body, NotesDir, Current, g
    SaveCurrent()
    Current := name
    f := NotesDir "\" name ".md"
    body.Value := FileExist(f) ? FileRead(f, "UTF-8") : ""
    g.Status("msg", name)
}
SaveCurrent(*) {
    global body, NotesDir, Current
    if (Current = "")
        return
    f := NotesDir "\" Current ".md"
    try FileDelete(f)
    FileAppend(body.Value, f, "UTF-8")
}
NewNote() {
    global g, list, NotesDir
    name := Trim(g.Prompt("What is it called?", "New note", "", "A name for the note"))
    if (name = "")
        return
    name := RegExReplace(name, '[\\/:*?"<>|]', "-")
    if FileExist(NotesDir "\" name ".md")
        return g.Toast("There is already a note called " name, 2500, "warning")
    FileAppend("# " name "`n`n", NotesDir "\" name ".md", "UTF-8")
    LoadNotes()
    list.Value := name
    OpenNote(name)
    g.Toast("Added " name, 1500, "success")
}
DeleteNote() {
    global g, body, NotesDir, Current
    if (Current = "")
        return g.Toast("Pick a note first", 1500, "warning")
    if !g.Confirm("Delete " Current "?", "Notes", "Delete", "Keep it")
        return
    try FileDelete(NotesDir "\" Current ".md")
    Current := "", body.Value := ""
    LoadNotes()
}
